import type { Assignment, AuditEntry, Order, PricedItem } from '../../shared/types';
import { api, money, dateTime, notifyError, exportFile, copyText } from '../lib/api';
import { state, refresh, can, orderProgress, authenticated } from '../lib/store';
import MemberBadge from '../components/MemberBadge.vue';
import PlayerGender from '../components/PlayerGender.vue';
import PriceBreakdown from '../components/PriceBreakdown.vue';
import { itemPriceExplanation, quotePriceFormula, groupPriceExplanations, priceDiscountLabel } from '../../shared/priceExplanation';
import { playerSelectionLabel } from '../lib/playerDisplay';
import { registerEditorLeaveGuard } from '../lib/leaveGuard';

type Operation = 'confirm' | 'pay' | 'assign' | 'replace' | 'free' | 'earning' | 'refund' | 'owner' | 'cancel' | 'adjustment';
const route = useRoute(), router = useRouter();
const editorOwner = state.user.id;
let alive = true, internalNavigation = false;
const stillActive = () => alive && authenticated.value && state.user.id === editorOwner;
const search = ref(''), stageFilter = ref(routeStage()), mineOnly = ref(route.query.mine === '1');
const dates = ref<string[]>([]), page = ref(1), pageSize = ref(10), detailOpen = ref(false), detailId = ref(''), detailTab = ref('items'), busy = ref(false);
const operationOpen = ref(false), operationKind = ref<Operation>('confirm'), previewOpen = ref(false);
const op = reactive({ orderId: '', code: '', customerName: '', totalCents: 0, quoteVersion: 0, version: 0, idempotencyKey: '', itemId: '', assignmentId: '', playerId: '', note: '', reference: '', channel: '微信转账', mode: 'wallet', wallet: 0, external: 0, allowConflict: false, minutes: 10, reason: '', earning: 0, settled: false, cancelRemaining: false, ownerId: '', adjustmentAmount: null as number | null, adjustmentDirection: 'increase' });
const stages = ['待确认 / 待收款', '待安排陪玩', '待客户确认', '待结清', '待派单', '部分派单', '待服务', '服务中', '已完成', '已结清补款', '已取消'];
const selected = computed(() => state.orders.find(o => o.id === detailId.value));
const customer = computed(() => state.customers.find(c => c.id === selected.value?.customerId));
