const linkedOrders = computed(() => state.orders.filter(o => o.parentOrderId === selected.value?.id));
const adjustmentDelta = computed(() => Math.round((op.adjustmentAmount || 0) * 100) * (op.adjustmentDirection === 'decrease' ? -1 : 1));
const adjustmentTarget = computed(() => selected.value?.payment ? Math.abs(adjustmentDelta.value) : op.totalCents + adjustmentDelta.value);
const filtered = computed(() => state.orders.filter(o => {
  const term = search.value.trim().toLowerCase(), date = new Date(o.createdAt).toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' });
  const stageMatch = !stageFilter.value || (stageFilter.value === '待确认 / 待收款' ? ['draft', 'confirmed'].includes(o.status) : stageFilter.value === '待安排陪玩' ? ['待派单', '部分派单'].includes(orderProgress(o)) : orderProgress(o) === stageFilter.value);
  return (!term || `${o.code} ${o.customerName} ${o.items.map(i => `${i.mode}${i.tier}`).join(' ')}`.toLowerCase().includes(term)) && stageMatch && (!mineOnly.value || o.ownerId === state.user.id) && (!dates.value?.length || (date >= dates.value[0]! && date <= dates.value[1]!));
}));
const pageOrders = computed(() => filtered.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value));
const pendingConfirm = computed(() => state.orders.filter(o => o.status === 'draft').length);
const pendingDispatch = computed(() => state.orders.filter(o => ['待派单', '部分派单'].includes(orderProgress(o))).length);
const servingCount = computed(() => state.orders.filter(o => orderProgress(o) === '服务中').length);
const walletRefunded = computed(() => selected.value?.refunds.reduce((s, r) => s + r.walletCents, 0) || 0);
const externalRefunded = computed(() => selected.value?.refunds.reduce((s, r) => s + r.externalCents, 0) || 0);
const walletRefundable = computed(() => Math.max(0, (selected.value?.payment?.walletCents || 0) - walletRefunded.value));
const externalRefundable = computed(() => Math.max(0, (selected.value?.payment?.externalCents || 0) - externalRefunded.value));
const paidHasService = computed(() => !!selected.value?.assignments.some(a => a.startedAt));
const staffRefundLimit = computed(() => {
  const order = selected.value;
  if (!order) return 0;
  const unstarted = order.items.filter(i => !order.assignments.some(a => a.itemId === i.id && a.startedAt)).reduce((sum, i) => sum + i.totalCents, 0);
  return Math.max(0, unstarted + Math.min(0, order.adjustmentCents) - walletRefunded.value - externalRefunded.value);
});
const canRefund = computed(() => can('refund') && (isAdmin.value || staffRefundLimit.value > 0));
const activeAssignment = computed(() => selected.value?.assignments.find(a => a.id === op.assignmentId));
const operationItem = computed(() => selected.value?.items.find(i => i.id === op.itemId));
const candidates = computed(() => {
  const i = operationItem.value;
  return i ? state.players.filter(p => p.status === 'available' && p.id !== (operationKind.value === 'replace' ? activeAssignment.value?.playerId : '') && (!i.female || p.gender === '女') && p.capabilities.some(c => c.mode === i.mode && c.tier === i.tier)) : [];
});
const relatedAudit = computed(() => state.audit.filter(a => a.targetId === detailId.value || a.before?.orderId === detailId.value || a.after?.orderId === detailId.value));
const operationTitle = computed(() => ({ confirm: '登记客户确认', pay: '确认订单结清', assign: '为服务明细派单', replace: '更换陪玩成员', free: '登记免费补时 / 补打', earning: '登记成员应得金额', refund: '登记订单退款', owner: '交接跟进客服', cancel: selected.value?.payment&&selected.value.totalCents===0?'取消零元订单':'取消未结清订单', adjustment: '特殊情况增减款' })[operationKind.value]);
const quoteText = computed(() => selected.value ? confirmationText(selected.value) : '');
watch([search, stageFilter, mineOnly, dates], () => { page.value = 1; });
watch(() => route.query.orderId, id => { if (typeof id === 'string') showDetail(id, false); else { detailOpen.value = false; operationOpen.value = false; previewOpen.value = false; } }, { immediate: true });
watch(detailOpen, open => { if (!open && route.path === '/orders' && route.query.orderId) { const query = { ...route.query }; delete query.orderId; void router.replace({ path: '/orders', query }); } });
watch(() => [route.query.status, route.query.stage, route.query.filter], () => { stageFilter.value = routeStage(); });
watch(() => op.mode, mode => {
  if (operationKind.value !== 'pay') return;
