  else { op.wallet = Math.min(customer.value?.balanceCents || 0, op.totalCents) / 100; op.external = (op.totalCents - Math.round(op.wallet * 100)) / 100; }
});
watch(() => op.wallet, amount => { if (operationKind.value === 'pay' && op.mode === 'mixed') op.external = Math.max(0, op.totalCents - Math.round(amount * 100)) / 100; });
function routeStage() { return String(route.query.status || route.query.stage || ({ unpaid: '待确认 / 待收款', dispatch: '待安排陪玩', serving: '服务中' } as Record<string, string>)[String(route.query.filter)] || ''); }
function staffName(id: string) { return state.staff.find(s => s.id === id)?.name || '原跟进客服'; }
function progressTone(o: Order) { const p = orderProgress(o); return ['已完成', '已结清补款'].includes(p) ? 'success' : p === '服务中' ? 'primary' : p === '已取消' ? 'info' : 'warning'; }
function paymentLabel(o: Order) { const r = o.refunds.reduce((s, x) => s + x.walletCents + x.externalCents, 0); return !o.payment ? '未结清' : r >= o.totalCents && r > 0 ? '已全额退款' : r > 0 ? '部分退款' : '已结清'; }
function assignmentLabel(status: Assignment['status']) { return ({ assigned: '待服务', serving: '服务中', completed: '已完成', replaced: '已换人', cancelled: '已取消' } as const)[status]; }
function discountLabel(i: PricedItem) { return priceDiscountLabel(i); }
function live(itemId: string) { return selected.value?.assignments.find(a => a.itemId === itemId && !['replaced', 'cancelled'].includes(a.status)); }
function playerGender(id: string | undefined) { return state.players.find(p => p.id === id)?.gender || '未注明'; }
function showDetail(id: string, syncUrl = true) { if (busy.value && !internalNavigation) return; if (detailId.value !== id) { operationOpen.value = false; previewOpen.value = false; } detailId.value = id; detailTab.value = 'items'; detailOpen.value = true; if (syncUrl && route.query.orderId !== id) void router.replace({ path: '/orders', query: { ...route.query, orderId: id } }); }
function showRow(o: Order) { showDetail(o.id); }
function assignmentItem(a: Assignment) { return selected.value?.items.find(i => i.id === a.itemId); }
function playerArrangements(playerId: string) { return state.orders.flatMap(o => o.assignments.filter(a => a.playerId === playerId && ['assigned', 'serving'].includes(a.status) && a.id !== op.assignmentId)); }
function confirmationText(o: Order) {
  const lines = [`【${state.settings.clubName || '贝蒂电竞俱乐部'} · 订单确认】`, `订单：${o.code}（第${o.quoteVersion}版）`, `客户：${o.customerName}`, ''];
  if (o.kind === 'supplement') lines.push('类型：关联补款单（不新增服务时长）', `原订单：${state.orders.find(p => p.id === o.parentOrderId)?.code || o.parentOrderId}`, `补款说明：${o.adjustmentReason}`, '');
  o.items.forEach((i, n) => {
    const a = o.assignments.find(a => a.itemId === i.id && !['replaced', 'cancelled'].includes(a.status));
    const requested = state.players.find(p => p.id === i.requestedPlayerId);
    lines.push(`${n + 1}. ${i.kind === 'trial' ? '新客体验 · ' : ''}${i.mode} / ${i.tier}，陪玩1位，客户${i.customerCount}位，${i.hours}小时`, `   人选：${a?.playerName || (requested ? `指定${requested.name}` : '按档位安排')}；本项报价 ${money(i.totalCents)}`);
    const explanation = itemPriceExplanation(i);
    lines.push(...explanation.steps.map(step => `   ${step}`), `   计算式：${explanation.formula}`, ...explanation.notes.map(note => `   ${note}`));
    if (i.plannedStart) lines.push(`   预约：${dateTime(i.plannedStart)}`);
    if (i.promise) lines.push(`   服务承诺：${i.promise}`);
  });
  lines.push('');
  lines.push(...groupPriceExplanations(o.items).map(g => g.formula));
  if (o.groupDiscountCents) lines.push(`双陪整组减免共 ${money(o.groupDiscountCents)}，已计入上述报价。`);
  if (o.discountCents) lines.push(`比例折扣优惠共 ${money(o.discountCents)}，已计入上述报价。`);
  if (o.adjustmentCents) lines.push(`整单约定调整：${o.adjustmentCents > 0 ? '+' : ''}${money(o.adjustmentCents)}`);
  lines.push(`合计计算式：${quotePriceFormula(o.items, o.totalCents, o.adjustmentCents)}`, `本单应付合计：${money(o.totalCents)}`);
  if (o.promise) lines.push(`本单约定：${o.promise}`);
