function openOperation(kind: Operation, order?: Order, item?: PricedItem, a?: Assignment) {
  if (busy.value) return;
  if (order) detailId.value = order.id;
  const o = selected.value; if (!o) return;
  if (kind === 'adjustment' && !isAdmin.value) return ElMessage.warning('特殊情况增减款需管理员操作');
  operationKind.value = kind;
  Object.assign(op, { orderId: o.id, code: o.code, customerName: o.customerName, totalCents: o.totalCents, quoteVersion: o.quoteVersion, version: o.version, idempotencyKey: crypto.randomUUID(), itemId: item?.id || a?.itemId || '', assignmentId: a?.id || '', playerId: kind === 'assign' ? item?.requestedPlayerId || '' : '', note: '', reference: '', channel: '微信转账', mode: 'wallet', wallet: 0, external: 0, allowConflict: false, minutes: 10, reason: '', earning: (a?.earningCents || 0) / 100, settled: a?.settled || false, cancelRemaining: false, ownerId: o.ownerId, adjustmentAmount: null, adjustmentDirection: o.kind === 'supplement' && o.payment ? 'decrease' : 'increase' });
  if (kind === 'pay') { const w = Math.min(customer.value?.balanceCents || 0, o.totalCents); op.mode = w >= o.totalCents ? 'wallet' : w > 0 ? 'mixed' : 'external'; op.wallet = w / 100; op.external = (o.totalCents - w) / 100; }
  if (kind === 'refund') {
    const cap = isAdmin.value ? walletRefundable.value + externalRefundable.value : Math.min(staffRefundLimit.value, walletRefundable.value + externalRefundable.value);
