  const kind = operationKind.value; let suffix: string = kind; let body: Record<string, unknown> = {};
  const w = Math.round((op.wallet || 0) * 100), e = Math.round((op.external || 0) * 100);
  if (kind === 'confirm') body = { note: op.note || '客服已与客户确认本版服务安排及总价', quoteVersion: op.quoteVersion, version: op.version };
  if (kind === 'pay') {
    if (w < 0 || e < 0 || w + e !== op.totalCents) { ElMessage.warning('余额抵扣与外部到账合计须等于本单应付'); return; }
    if (w > (customer.value?.balanceCents || 0)) { ElMessage.warning('客户余额不足，请调整抵扣或先登记充值'); return; }
    if (e && !op.reference.trim()) { ElMessage.warning('请填写实际到账参考号或凭据说明'); return; }
    body = { walletCents: w, externalCents: e, channel: op.channel, reference: op.reference.trim(), note: op.note, quoteVersion: op.quoteVersion, version: op.version };
  }
  if (kind === 'assign' || kind === 'replace') {
    if (!op.playerId) { ElMessage.warning('请选择陪玩成员'); return; }
    if ((kind === 'replace' || op.allowConflict || (operationItem.value?.requestedPlayerId && operationItem.value.requestedPlayerId !== op.playerId)) && !op.reason.trim()) { ElMessage.warning('请说明客户同意换人或已协调安排的情况'); return; }
    body = { itemId: op.itemId, playerId: op.playerId, reason: op.reason, allowConflict: op.allowConflict };
    if (kind === 'replace') { suffix = `assignment/${op.assignmentId}`; body.action = 'replace'; }
  }
  if (kind === 'free') { if (!(op.minutes > 0) || !Number.isInteger(op.minutes) || !op.reason.trim()) { ElMessage.warning('请填写有效分钟数和处理原因'); return; } suffix = `assignment/${op.assignmentId}`; body = { action: 'free', minutes: op.minutes, reason: op.reason, idempotencyKey: op.idempotencyKey }; }
  if (kind === 'earning') { if (op.earning < 0) { ElMessage.warning('应得金额不能小于零'); return; } suffix = `assignment/${op.assignmentId}`; body = { action: 'earning', earningCents: Math.round(op.earning * 100), settled: op.settled, reason: op.reason }; }
  if (kind === 'refund') {
    if (w + e <= 0 || w < 0 || e < 0 || w > walletRefundable.value || e > externalRefundable.value) { ElMessage.warning('请核对退款金额，不得超过各付款来源剩余可退金额'); return; }
    if (!isAdmin.value && w + e > staffRefundLimit.value) { ElMessage.warning(`客服本单最多可退未开始服务金额 ${money(staffRefundLimit.value)}，已消费退费请交管理员处理`); return; }
    if (!op.reason.trim() || (e > 0 && !op.reference.trim())) { ElMessage.warning('请填写处理原因，外部退款还需实际退款参考号'); return; }
    body = { walletCents: w, externalCents: e, reason: op.reason, reference: op.reference.trim(), cancelRemaining: op.cancelRemaining, idempotencyKey: op.idempotencyKey };
  }
  if (kind === 'adjustment') {
    const amount = Math.abs(adjustmentDelta.value), order = selected.value;
    if (!order || order.id !== op.orderId || !isAdmin.value) return ElMessage.warning('请由管理员重新打开本订单处理');
    if (!Number.isFinite(amount) || amount <= 0 || !op.reason.trim()) return ElMessage.warning('请填写大于零的金额及调整原因');
    if (order.payment && op.adjustmentDirection === 'decrease') {
      if (amount > walletRefundable.value + externalRefundable.value) return ElMessage.warning('减款金额超过本单剩余可退款金额');
      const reason = op.reason.trim(); openOperation('refund');
      op.wallet = Math.min(walletRefundable.value, amount) / 100; op.external = (amount - Math.round(op.wallet * 100)) / 100; op.reason = reason;
      return;
    }
    if (!order.payment && adjustmentTarget.value < 0) return ElMessage.warning('调整后的应付金额不能小于零');
    suffix = order.payment ? 'supplement' : 'adjustment';
    body = { version: op.version, quoteVersion: op.quoteVersion, amountCents: order.payment ? amount : adjustmentDelta.value, reason: op.reason.trim(), idempotencyKey: op.idempotencyKey };
  }
  if (kind === 'owner') { if (!op.ownerId || !op.reason.trim()) { ElMessage.warning('请选择接手客服并填写交接说明'); return; } body = { ownerId: op.ownerId, reason: op.reason }; }
  if (kind === 'cancel') { if (!op.reason.trim()) { ElMessage.warning('请填写取消原因'); return; } body = { reason: op.reason }; }
  busy.value = true;
  try {
    const result = await api<Order>(`/api/orders/${op.orderId}/${suffix}`, { method: 'POST', body: JSON.stringify(body) });
    if (!stillActive()) return;
    mergeOrder(result);
    operationOpen.value = false;
    if (kind === 'adjustment') { internalNavigation = true; try { showDetail(result.id, false); if (suffix === 'supplement') await router.replace({path:'/orders',query:{orderId:result.id}}); } finally { internalNavigation = false; } }
    if (!stillActive()) return;
    if (['assign', 'replace', 'free', 'earning'].includes(kind)) detailTab.value = 'service'; if (['pay', 'refund'].includes(kind)) detailTab.value = 'payment';
    ElMessage.success(kind === 'adjustment' ? suffix === 'supplement' ? '关联补款单已生成，请客户确认后再结清' : '金额已调整，请重新发送确认单并登记客户确认' : `${operationTitle.value}已保存`);
    try { await refresh(true); } catch { if (stillActive()) ElMessage.warning('本次记录已保存，列表暂未刷新，请勿重复提交'); }
  }
  catch (error) { if (stillActive()) notifyError(error); } finally { busy.value = false; }
}
function mergeOrder(order: Order) { const index = state.orders.findIndex(o => o.id === order.id); if (index < 0) state.orders.unshift(order); else if (state.orders[index].version <= order.version) state.orders[index] = order; }
async function serviceAction(a: Assignment, action: 'start' | 'complete') {
  if (!selected.value || busy.value || !stillActive()) return;
  const orderId = selected.value.id;
  busy.value = true;
  try {
    await ElMessageBox.confirm(action === 'start' ? `确认已与客户及「${a.playerName}」确认开始服务？` : `确认「${a.playerName}」已结束本次服务？补打或售后请继续记录处理。`, action === 'start' ? '登记服务开始' : '登记服务完成', { confirmButtonText: '确认登记', cancelButtonText: '取消', type: 'info' });
    if (!stillActive()) return;
    const result = await api<Order>(`/api/orders/${orderId}/assignment/${a.id}`, { method: 'POST', body: JSON.stringify({ action }) });
    if (!stillActive()) return;
    mergeOrder(result); ElMessage.success('实际服务时间已记录');
    try { await refresh(true); } catch { if (stillActive()) ElMessage.warning('服务记录已保存，列表暂未刷新，请勿重复登记'); }
  } catch (error) { if (stillActive() && error !== 'cancel' && error !== 'close') notifyError(error); } finally { busy.value = false; }
}
async function copyOrder(order?: Order) {
  if (busy.value || !stillActive()) return;
  if (order) detailId.value = order.id;
