  const snapshot: Order = JSON.parse(JSON.stringify(selected.value)), text = confirmationText(snapshot); busy.value = true;
  try {
    const result = await api<Order>(`/api/orders/${snapshot.id}/copy`, { method: 'POST', body: JSON.stringify({ quoteVersion: snapshot.quoteVersion }) });
