    mergeOrder(result);
    await copyText(text);
    if (!stillActive()) return;
    ElMessage.success('确认单已复制，请由客服发送；客户确认后另行登记');
    try { await refresh(true); } catch { if (stillActive()) ElMessage.warning('确认单已复制，列表暂未刷新'); }
  } catch (error) { if (stillActive()) { notifyError(error); previewOpen.value = true; } } finally { busy.value = false; }
}
function allowExit() { if (busy.value && !internalNavigation) { ElMessage.warning('正在保存订单操作，请稍候再离开'); return false; } return true; }
const unregisterLeaveGuard = registerEditorLeaveGuard(async () => allowExit());
onBeforeRouteLeave(allowExit);
onBeforeRouteUpdate((to, from) => to.path === '/orders' && to.query.orderId === detailId.value && to.query.orderId !== from.query.orderId ? true : allowExit());
function beforeUnload(event: BeforeUnloadEvent) { if (busy.value) { event.preventDefault(); event.returnValue = ''; } }
onMounted(() => window.addEventListener('beforeunload', beforeUnload));
onBeforeUnmount(() => { alive = false; unregisterLeaveGuard(); window.removeEventListener('beforeunload', beforeUnload); });
async function download() { try { await exportFile('orders', 'xlsx', { from: dates.value?.[0] || '', to: dates.value?.[1] || '' }); } catch (error) { notifyError(error); } }
function auditChanges(a: AuditEntry) {
  const labels: Record<string, string> = { totalCents: '应付金额', walletCents: '余额抵扣', externalCents: '外部收款', balanceCents: '客户余额', status: '状态', quoteVersion: '报价版本', playerName: '陪玩成员', ownerId: '跟进客服', freeMinutes: '免费分钟', earningCents: '成员应得', reference: '外部参考', startedAt: '服务开始', endedAt: '服务结束', settled: '结算登记' };
  return [...new Set([...Object.keys(a.before || {}), ...Object.keys(a.after || {})])].filter(k => !/password|token|secret|items|capabilities/i.test(k) && JSON.stringify(a.before?.[k]) !== JSON.stringify(a.after?.[k])).map(k => ({ label: labels[k] || k, before: auditValue(k, a.before?.[k]), after: auditValue(k, a.after?.[k]) }));
}
function auditValue(k: string, v: unknown): string { if (v === undefined || v === null) return '—'; if (k.endsWith('Cents') && typeof v === 'number') return money(v); if (typeof v === 'boolean') return v ? '是' : '否'; if (k === 'ownerId') return staffName(String(v)); if (k.endsWith('At')) return dateTime(String(v)); return typeof v === 'object' ? JSON.stringify(v) : String(v); }
</script>

<template>
