    <template v-if="selected"><div class="detail-hero"><div><div class="order-kicker">{{selected.kind==='supplement'?'SUPPLEMENT · 关联补款':'ORDER'}} · 第 {{ selected.quoteVersion }} 版报价</div><h2>{{ selected.code }} <el-tag :type="progressTone(selected)">{{ orderProgress(selected) }}</el-tag></h2><p>{{ selected.customerName }} <MemberBadge :member="selected.member" /> · {{ selected.benefit === 'wechat' ? '微信权益' : selected.member === '普通客户' ? '标准价' : '折扣权益' }} <span>跟进：{{ staffName(selected.ownerId) }}</span></p></div><div class="detail-total"><small>本单应付</small><strong>{{ money(selected.totalCents) }}</strong><span>{{ paymentLabel(selected) }}</span></div></div>
