</strong></div><p class="total-formula">{{quotePriceFormula(selected.items,selected.totalCents,selected.adjustmentCents)}}</p><div class="summary-final"><span>应付合计</span><strong>{{ money(selected.totalCents) }}</strong></div></div><section v-if="selected.adjustments?.length" class="adjustment-history"><h3>特殊金额调整记录</h3><div v-for="entry in selected.adjustments" :key="entry.id"><div><b>{{entry.amountCents>0?'+':''}}{{money(entry.amountCents)}}</b><span>{{entry.reason}}</span></div><small>{{entry.actorName}} · {{dateTime(entry.createdAt)}} · 第{{entry.quoteVersion}}版 · {{money(entry.previousTotalCents)}} → {{money(entry.totalCents)}}</small></div></section><section v-if="linkedOrders.length" class="linked-orders"><h3>关联续单 / 补款单</h3><el-button v-for="child in linkedOrders" :key="child.id" link type="primary" @click="showDetail(child.id)">{{child.code}} · {{child.kind==='supplement'?'补款':'续单'}} · {{money(child.totalCents)}} · {{orderProgress(child)}}</el-button></section><el-descriptions :column="2" border><el-descriptions-item label="客户确认">{{ dateTime(selected.customerConfirmedAt) }}</el-descriptions-item><el-descriptions-item label="最近复制">{{ dateTime(selected.copiedAt) }}</el-descriptions-item><el-descriptions-item label="创建客服">{{ selected.createdByName }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ dateTime(selected.createdAt) }}</el-descriptions-item><el-descriptions-item v-if="selected.parentOrderId" label="关联原订单" :span="2"><el-button link type="primary" @click="showDetail(selected.parentOrderId!)">查看原订单</el-button></el-descriptions-item><el-descriptions-item label="对客服务约定" :span="2">{{ selected.promise || '按本单明细执行' }}</el-descriptions-item><el-descriptions-item label="内部备注" :span="2">{{ selected.notes || '暂无备注' }}</el-descriptions-item><el-descriptions-item v-if="selected.adjustmentReason" label="调价原因" :span="2">{{ selected.adjustmentReason }}</el-descriptions-item></el-descriptions></el-tab-pane>
      <el-tab-pane label="收款与退款" name="payment"><div class="payment-stats"><div><small>余额抵扣</small><strong>{{ money(selected.payment?.walletCents || 0) }}</strong></div><div><small>本单外部收款</small><strong>{{ money(selected.payment?.externalCents || 0) }}</strong></div><div><small>已登记退款</small><strong>{{ money(walletRefunded + externalRefunded) }}</strong></div></div><el-empty v-if="!selected.payment" description="本单尚未结清"><el-button v-if="selected.status === 'draft'" @click="openOperation('confirm')">先登记客户确认</el-button><el-button v-else-if="selected.status === 'confirmed' && can('payment')" type="primary" @click="openOperation('pay')">确认结清</el-button></el-empty><template v-else><el-descriptions :column="2" border><el-descriptions-item label="结清时间">{{ dateTime(selected.payment.createdAt) }}</el-descriptions-item><el-descriptions-item label="经办客服">{{ selected.payment.actorName }}</el-descriptions-item><el-descriptions-item label="外部收款渠道">{{ selected.payment.externalCents > 0 ? selected.payment.channel : '余额付款（无外部收款）' }}</el-descriptions-item><el-descriptions-item label="外部参考号">{{ selected.payment.reference || '—' }}</el-descriptions-item><el-descriptions-item label="收款备注" :span="2">{{ selected.payment.note || '暂无备注' }}</el-descriptions-item></el-descriptions><div class="section-heading refund-heading"><h3 class="section-title">退款记录</h3><el-button v-if="canRefund && walletRefundable + externalRefundable > 0" type="danger" plain @click="openOperation('refund')">登记退款</el-button></div><p v-if="paidHasService && !isAdmin" class="muted helper">客服可退未开始部分：{{ money(staffRefundLimit) }}。已消费部分退费请交管理员处理。</p><el-table :data="selected.refunds" empty-text="暂无退款记录"><el-table-column label="时间" min-width="165"><template #default="{ row }">{{ dateTime(row.createdAt) }}</template></el-table-column><el-table-column label="退回余额" min-width="115" align="right"><template #default="{ row }">{{ money(row.walletCents) }}</template></el-table-column><el-table-column label="外部退款" min-width="115" align="right"><template #default="{ row }">{{ money(row.externalCents) }}</template></el-table-column><el-table-column prop="actorName" label="经办人" min-width="100" /><el-table-column prop="reason" label="处理原因" min-width="190" show-overflow-tooltip /><el-table-column prop="reference" label="退款参考" min-width="150" show-overflow-tooltip /></el-table><el-alert title="外部资金操作由工作人员在对应渠道完成，系统保存核实后的记录。" type="info" :closable="false" show-icon class="detail-alert spaced" /></template></el-tab-pane>
      <el-tab-pane label="派单与服务" name="service"><el-alert v-if="selected.kind==='supplement'" title="补款单不另行派单，服务安排请查看关联原订单。" type="info" :closable="false" show-icon class="detail-alert" /><el-alert v-if="!selected.payment&&selected.kind!=='supplement'" title="本单需客户确认并结清后才能派单。" type="warning" :closable="false" show-icon class="detail-alert" /><div v-for="(i, n) in selected.items" :key="i.id" class="dispatch-card"><div class="section-heading"><div><span class="item-index">{{ String(n + 1).padStart(2, '0') }}</span><strong>{{ i.mode }} · {{ i.tier }} / {{ i.hours }}小时</strong></div><el-button v-if="selected.status === 'paid' && !live(i.id)" type="primary" size="small" @click="openOperation('assign', undefined, i)">指定陪玩</el-button><el-tag v-else-if="live(i.id)" :type="live(i.id)?.status === 'serving' ? 'success' : 'info'" size="small">{{ assignmentLabel(live(i.id)!.status) }}</el-tag></div><div class="dispatch-meta"><span>预约：{{ i.plannedStart ? dateTime(i.plannedStart) : '即约 / 待协调' }}</span><span v-if="i.requestedPlayerId">客户指定：{{ state.players.find(p => p.id === i.requestedPlayerId)?.name || '已登记成员' }}</span></div><div v-if="live(i.id)" class="assigned-person"><div><span class="person-avatar">{{ live(i.id)!.playerName.slice(0, 1) }}</span><div><strong>{{ live(i.id)!.playerName }} <PlayerGender :gender="playerGender(live(i.id)!.playerId)" /></strong><p>{{ live(i.id)!.startedAt ? `实际开始 ${dateTime(live(i.id)!.startedAt)}` : '尚未登记实际开始' }}</p></div></div><div class="service-buttons"><el-button v-if="selected.status === 'paid' && live(i.id)!.status === 'assigned'" type="success" plain size="small" :loading="busy" @click="serviceAction(live(i.id)!, 'start')">开始服务</el-button><el-button v-if="selected.status === 'paid' && live(i.id)!.status === 'serving'" type="success" size="small" :loading="busy" @click="serviceAction(live(i.id)!, 'complete')">完成服务</el-button><el-button v-if="selected.status === 'paid' && ['assigned', 'serving'].includes(live(i.id)!.status)" size="small" @click="openOperation('replace', undefined, i, live(i.id))">换人</el-button><el-button v-if="selected.status === 'paid'" size="small" @click="openOperation('free', undefined, i, live(i.id))">赠时 / 补打</el-button></div></div><div v-else class="unassigned"><span>尚未安排成员</span><span class="muted">按本条服务要求匹配成员</span></div><div v-if="live(i.id)?.freeMinutes" class="free-note">免费服务 {{ live(i.id)!.freeMinutes }} 分钟 · {{ live(i.id)!.freeReason }}</div></div><h3 class="section-title history-heading">派单与换人历史</h3><el-table :data="selected.assignments" empty-text="尚无派单记录"><el-table-column label="成员 / 服务" min-width="170"><template #default="{ row }"><strong>{{ row.playerName }} <PlayerGender :gender="playerGender(row.playerId)" /></strong><div class="muted tiny">{{ assignmentItem(row)?.mode }} · {{ assignmentItem(row)?.tier }}</div></template></el-table-column><el-table-column label="状态" min-width="95"><template #default="{ row }"><el-tag :type="row.status === 'serving' ? 'success' : 'info'" size="small">{{ assignmentLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="实际起止" min-width="170"><template #default="{ row }"><div>{{ dateTime(row.startedAt) }}</div><div class="muted tiny">{{ dateTime(row.endedAt) }}</div></template></el-table-column><el-table-column label="补时与说明" min-width="190"><template #default="{ row }"><div v-if="row.freeMinutes">免费 {{ row.freeMinutes }} 分钟</div><span class="muted tiny">{{ row.freeReason || row.reason || '—' }}</span></template></el-table-column><el-table-column v-if="isAdmin" label="成员应得" min-width="120" align="right"><template #default="{ row }">{{ money(row.earningCents) }}<div class="muted tiny">{{ row.settled ? '已登记结算' : '未登记结算' }}</div></template></el-table-column><el-table-column v-if="isAdmin" label="登记" min-width="100" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openOperation('earning', undefined, undefined, row)">应得金额</el-button></template></el-table-column></el-table><el-alert title="补打和赠时不收费。新增收费请创建续单，保留客户对费用的确认记录。" type="info" :closable="false" show-icon class="detail-alert spaced" /></el-tab-pane>
      <el-tab-pane label="操作轨迹" name="audit"><el-timeline v-if="relatedAudit.length" class="audit-timeline"><el-timeline-item v-for="a in relatedAudit" :key="a.id" :timestamp="dateTime(a.createdAt)" placement="top" :type="a.result === 'success' ? 'primary' : 'danger'"><div class="audit-card"><div class="audit-heading"><strong>{{ a.action }}</strong><span>{{ a.actorName }}</span><el-tag v-if="a.result !== 'success'" type="danger" size="small">{{ a.result }}</el-tag></div><div class="audit-changes"><div v-for="(c, n) in auditChanges(a)" :key="n"><span>{{ c.label }}</span><del>{{ c.before }}</del><b>→</b><strong>{{ c.after }}</strong></div></div><p v-if="a.reason">{{ a.reason }}</p></div></el-timeline-item></el-timeline><el-empty v-else description="暂无可见操作轨迹" /></el-tab-pane>
    </el-tabs></template><el-empty v-else description="未找到订单，请刷新后再试" />
  </el-drawer>

  <el-dialog v-model="previewOpen" title="客户确认单预览" width="min(680px, 96vw)" append-to-body><p class="muted helper">仅包含对客安排和价格，内部备注及成员应得金额不会进入确认单。</p><el-input :model-value="quoteText" type="textarea" :rows="18" readonly /><template #footer><el-button @click="previewOpen = false">关闭</el-button><el-button type="primary" :loading="busy" @click="copyOrder()">复制确认单</el-button></template></el-dialog>
  <el-dialog v-model="operationOpen" :show-close="!busy" :close-on-press-escape="!busy" :title="operationTitle" width="min(630px, 97vw)" :close-on-click-modal="!busy" append-to-body>
    <div class="operation-body" :inert="busy"><div class="operation-context"><div><strong>{{ op.customerName }}</strong><span>{{ op.code }} · 第{{ op.quoteVersion }}版</span></div><strong>{{ money(op.totalCents) }}</strong></div>
    <template v-if="operationKind === 'confirm'"><el-alert title="请确认客户已接受本版服务安排、时长、总价和承诺。此操作不扣款。" type="info" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="客户确认记录"><el-input v-model="op.note" type="textarea" :rows="3" maxlength="1000" placeholder="例如：客户在微信确认本版报价与预约安排" /></el-form-item></el-form></template>
    <template v-else-if="operationKind === 'pay'"><el-alert :title="selected?.kind==='supplement'?'核实补款后登记。余额扣款与收款记录一起保存，结清后无需另行派单。':'核实到账后登记。余额扣款与收款记录一起保存，结清后进入待派单。'" type="info" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="付款方式"><el-radio-group v-model="op.mode"><el-radio-button value="wallet" :disabled="(customer?.balanceCents || 0) < op.totalCents">余额付款</el-radio-button><el-radio-button value="external">直接转账</el-radio-button><el-radio-button value="mixed">余额＋转账</el-radio-button></el-radio-group></el-form-item><p class="balance-note">客户当前可用余额 <strong>{{ money(customer?.balanceCents) }}</strong></p><div class="form-grid"><el-form-item label="本单余额抵扣（元）"><el-input-number v-model="op.wallet" :min="0" :max="Math.min(customer?.balanceCents || 0, op.totalCents) / 100" :precision="2" :controls="false" :disabled="op.mode !== 'mixed'" /></el-form-item><el-form-item label="本单外部到账（元）"><el-input-number v-model="op.external" :min="0" :precision="2" :controls="false" disabled /></el-form-item></div><div class="payment-check"><span>两项合计</span><strong>{{ money(Math.round((op.wallet + op.external) * 100)) }}</strong><el-tag size="small" :type="Math.round((op.wallet + op.external) * 100) === op.totalCents ? 'success' : 'danger'">{{ Math.round((op.wallet + op.external) * 100) === op.totalCents ? '金额相符' : '金额不符' }}</el-tag></div><div v-if="op.external > 0" class="form-grid"><el-form-item label="收款渠道" required><el-select v-model="op.channel"><el-option v-for="c in ['微信转账', '支付宝', '银行转账', '现金']" :key="c" :label="c" :value="c" /></el-select></el-form-item><el-form-item label="到账参考号 / 凭据说明" required><el-input v-model="op.reference" maxlength="120" placeholder="须为本单直接收款，避免重复登记" /></el-form-item></div><el-form-item label="结清备注"><el-input v-model="op.note" type="textarea" :rows="2" maxlength="1000" /></el-form-item></el-form></template>
    <template v-else-if="operationKind === 'assign' || operationKind === 'replace'"><div v-if="operationItem" class="operation-service"><strong>{{ operationItem.mode }} · {{ operationItem.tier }}</strong><span>{{ operationItem.hours }}小时 · {{ operationItem.female ? '指定女陪' : '按档位匹配' }}</span><span>{{ operationItem.plannedStart ? dateTime(operationItem.plannedStart) : '即约 / 待协调' }}</span></div><el-alert v-if="operationKind === 'replace'" title="开始后30分钟内不满意可免费换人1次；陪玩自身原因换人不占次数。原成员服务记录会保留，请记录协调结果。" type="info" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="选择匹配的陪玩成员" required><el-select v-model="op.playerId" filterable placeholder="按模式、档位及指定要求筛选"><el-option v-for="p in candidates" :key="p.id" :label="`${playerSelectionLabel(p)}${playerArrangements(p.id).length ? ' · 已有安排，请核对时段' : ' · 可接单'}`" :value="p.id"><div class="dispatch-choice"><b>{{p.name}}</b><PlayerGender :gender="p.gender"/><span>{{playerArrangements(p.id).length?'已有安排，请核对时段':'可接单'}}</span></div></el-option></el-select><p v-if="!candidates.length" class="muted helper">暂无匹配且可接单的成员，请先核实服务能力与接单状态。</p></el-form-item><el-form-item label="安排说明 / 客户同意记录" :required="operationKind === 'replace' || op.allowConflict"><el-input v-model="op.reason" type="textarea" :rows="3" maxlength="1000" placeholder="换人、改变指定人选或冲突安排时请说明沟通结果" /></el-form-item><el-checkbox v-model="op.allowConflict">如存在预约冲突，已与双方协调本次安排</el-checkbox><p class="muted helper">系统检查预约冲突；确认冲突安排时必须填写说明。</p></el-form></template>
    <template v-else-if="operationKind === 'free'"><el-alert title="此处只增加免费时间，不产生收费或扣款。收费续时请创建续单。" type="info" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="免费服务分钟数" required><el-input-number v-model="op.minutes" :min="1" :max="10080" :precision="0" /><el-button class="ten-minute-button" @click="op.minutes = 10; op.reason = '漏提醒，按约定赠送10分钟'">漏提醒赠10分钟</el-button></el-form-item><el-form-item label="补时 / 补打原因" required><el-input v-model="op.reason" type="textarea" :rows="3" maxlength="1000" placeholder="例如：掉线补足、技术保障补打、漏提醒赠时" /></el-form-item></el-form></template>
    <template v-else-if="operationKind === 'earning'"><el-alert title="记录约定应得金额与人工结算情况，不发起实际付款。请结合优惠、补打及换人情况核定。" type="info" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="成员"><el-input :model-value="activeAssignment?.playerName" disabled /></el-form-item><el-form-item label="本条派单应得金额（元）" required><el-input-number v-model="op.earning" :min="0" :precision="2" :controls="false" /></el-form-item><el-form-item label="结算登记"><el-switch v-model="op.settled" active-text="已在线下完成结算" inactive-text="尚未结算" /></el-form-item><el-form-item label="登记说明"><el-input v-model="op.reason" type="textarea" :rows="2" maxlength="1000" /></el-form-item></el-form></template>
    <template v-else-if="operationKind === 'refund'"><el-alert :title="paidHasService ? (isAdmin ? '本单已有实际服务，请核实退费。外部退款先在线下完成，再登记实际结果。' : `客服仅可退未开始服务部分，本单最多 ${money(staffRefundLimit)}。外部退款请先在线下完成。`) : '请按核实金额登记。退余额会增加客户钱包，外部退款由工作人员实际完成后记录。'" type="warning" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><div class="form-grid"><el-form-item label="退回客户余额（元）"><el-input-number v-model="op.wallet" :min="0" :max="walletRefundable / 100" :precision="2" :controls="false" /><span class="muted tiny">此来源最多可退 {{ money(walletRefundable) }}</span></el-form-item><el-form-item label="已完成外部退款（元）"><el-input-number v-model="op.external" :min="0" :max="externalRefundable / 100" :precision="2" :controls="false" /><span class="muted tiny">此来源最多可退 {{ money(externalRefundable) }}</span></el-form-item></div><el-form-item v-if="op.external > 0" label="实际外部退款参考号 / 凭据说明" required><el-input v-model="op.reference" maxlength="120" /></el-form-item><el-form-item label="退款原因与客户确认结果" required><el-input v-model="op.reason" type="textarea" :rows="3" maxlength="1000" placeholder="说明取消的服务、金额与客户确认结果" /></el-form-item><el-checkbox v-model="op.cancelRemaining">同时结束本单剩余服务安排</el-checkbox><p class="muted helper">全额退款自动结束剩余安排；部分退款可按约定保留后续服务。</p></el-form></template>
    <template v-else-if="operationKind === 'adjustment'">
      <el-alert :title="selected?.payment ? '已结清订单保留原收款记录。增款生成关联补款单；减款进入按原付款来源退款的核实流程。' : '只调整本单费用，不改变服务明细。保存后将生成新版报价，原客户确认失效，需重新确认。'" type="warning" :closable="false" show-icon class="form-alert" />
      <el-form label-position="top"><el-form-item label="调整方向" required><el-radio-group v-model="op.adjustmentDirection"><el-radio-button value="increase" :disabled="selected?.kind==='supplement'&&!!selected?.payment">增加费用</el-radio-button><el-radio-button value="decrease">减少费用</el-radio-button></el-radio-group></el-form-item><el-form-item label="本次增减金额（元）" required><el-input-number v-model="op.adjustmentAmount" :min="0.01" :max="100000000" :precision="2" :controls="false" /></el-form-item><el-form-item :label="selected?.payment&&op.adjustmentDirection==='increase'?'补款说明（会显示在客户确认单）':'调整原因 / 约定备注'" required><el-input v-model="op.reason" type="textarea" :rows="3" maxlength="1000" placeholder="说明特殊情况、增减金额依据与客户沟通结果" /></el-form-item></el-form>
      <div class="adjustment-preview"><span>{{selected?.payment ? op.adjustmentDirection==='decrease'?'拟退款金额':'新补款单应付' : '调整后本单应付'}}</span><strong>{{money(adjustmentTarget)}}</strong><small v-if="!selected?.payment">{{money(op.totalCents)}} {{adjustmentDelta<0?'−':'+'}} {{money(Math.abs(adjustmentDelta))}} = {{money(adjustmentTarget)}}</small></div><p class="muted helper">保存操作者、时间、调整前后金额及备注。原订单的内部备注不会复制给客户。</p>
    </template>
    <template v-else-if="operationKind === 'owner'"><el-form label-position="top"><el-form-item label="接手客服" required><el-select v-model="op.ownerId" filterable><el-option v-for="s in state.staff" :key="s.id" :label="s.name" :value="s.id" /></el-select></el-form-item><el-form-item label="交接说明" required><el-input v-model="op.reason" type="textarea" :rows="4" maxlength="1000" placeholder="记录需求、当前进度与待处理事项" /></el-form-item></el-form></template>
    <template v-else-if="operationKind === 'cancel'"><el-alert :title="selected?.payment&&selected.totalCents===0?'取消零元订单会结束剩余派单，保留确认和服务历史，无需退款。':'取消后保留原报价和操作轨迹；已结清订单请通过退款处理。'" type="warning" :closable="false" show-icon class="form-alert" /><el-form label-position="top"><el-form-item label="取消原因" required><el-input v-model="op.reason" type="textarea" :rows="4" maxlength="1000" /></el-form-item></el-form></template>
    </div><template #footer><el-button :disabled="busy" @click="operationOpen = false">取消</el-button><el-button :type="['refund', 'cancel'].includes(operationKind) ? 'danger' : 'primary'" :loading="busy" @click="submitOperation">{{ operationKind === 'pay' ? '已核实，确认结清' : operationKind === 'refund' ? '确认登记退款' : operationKind === 'adjustment' ? selected?.payment ? op.adjustmentDirection==='decrease'?'下一步：核实退款':'生成关联补款单' : '保存调整并重新确认' : '确认保存记录' }}</el-button></template>
  </el-dialog>
</div>
